//! A grid item with an `aspect-ratio` takes at least the width of its content
//! when it states a `height` that is a percentage of the grid area, or none at
//! all, and a `max-height` below the padding and border it holds is raised to
//! them before the ratio carries it across to a maximum width: a `2 / 1` item
//! with 25px of border and `max-height: 40px` is 50px tall and 100px wide, not
//! 80px wide. A size the item states is no size the ratio gives, so the maximum
//! of the other axis leaves it alone, and an item is no narrower than the width
//! the ratio gives the padding and border it holds.
//!
//! The expected border boxes were recorded from Chromium for the same markup in
//! an 800px by 600px viewport, with the body margin of 8px. The items have a
//! 100px wide child and 25px of border unless a case says otherwise.

use raikiri_html::{
    FontCollectionBuilder, LayoutOptions, LayoutStatus, RenderResources, layout,
    parse_html_with_resources,
};
use raikiri_traits::{LayoutConfig, PageDefaults};

const AHEM: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/text-autospace/Ahem.ttf"
));

/// A border box `(x, y, width, height)`.
type Rect = (f32, f32, f32, f32);

/// A case: its name, its markup, and the border boxes by id.
type Case = (&'static str, &'static str, &'static [(&'static str, Rect)]);

/// The border boxes of the elements of `body` with an `id` on the first page.
fn border_boxes(body: &str) -> Vec<(String, Rect)> {
    let html = format!(
        "<!DOCTYPE html><style>@page {{ size: 800px 600px; margin: 0 }} \
         body {{ margin: 8px; font: 10px/10px Ahem }} div {{ box-sizing: border-box }}</style>{body}"
    );
    let fonts = FontCollectionBuilder::new()
        .font_bytes("Ahem", AHEM.to_vec())
        .build()
        .expect("fonts");
    let resources = RenderResources::new().fonts(fonts);
    let doc = parse_html_with_resources(html.as_bytes(), &resources).expect("parse");
    let status = layout(
        &doc,
        PageDefaults::default(),
        LayoutConfig::default(),
        LayoutOptions::new().resources(&resources),
    )
    .expect("layout");
    let LayoutStatus::Completed(result) = status else {
        panic!("expected a complete layout");
    };
    let page = result.pages().next().expect("a page");
    let dom = page.dom();
    page.fragments()
        .filter_map(|fragment| {
            let id = dom.attr(fragment.node(), "id")?;
            let rect = fragment.rect();
            Some((id.to_owned(), (rect.x, rect.y, rect.width, rect.height)))
        })
        .collect()
}

/// Layout units are 1/64px; allow a little more for the 32-bit sums.
const TOLERANCE: f32 = 0.02;

fn check(name: &str, body: &str, expected: &[(&str, Rect)]) {
    let actual = border_boxes(body);
    for &(id, (x, y, width, height)) in expected {
        let found = actual
            .iter()
            .find(|(box_id, _)| box_id == id)
            .unwrap_or_else(|| panic!("{name}: no fragment for #{id} in {body}"))
            .1;
        let close = |a: f32, b: f32| (a - b).abs() <= TOLERANCE;
        assert!(
            close(found.0, x)
                && close(found.1, y)
                && close(found.2, width)
                && close(found.3, height),
            "{name}: {body}: #{id} is {found:?}, expected {:?}",
            (x, y, width, height)
        );
    }
}

/// Run every case whose name satisfies `select`, and make sure some do.
fn check_group(select: fn(&str) -> bool) {
    let cases: Vec<&Case> = CASES.iter().filter(|case| select(case.0)).collect();
    assert!(!cases.is_empty(), "no case selected");
    for &&(name, body, expected) in &cases {
        check(name, body, expected);
    }
}

fn percentage_heights(name: &str) -> bool {
    name.starts_with("a_")
}

#[test]
fn an_item_with_a_percentage_height_is_as_wide_as_its_content() {
    check_group(percentage_heights);
}

fn maximum_heights(name: &str) -> bool {
    name.starts_with("b_")
}

#[test]
fn a_maximum_size_below_the_edges_of_the_item_is_raised_to_them() {
    check_group(maximum_heights);
}

fn stated_widths(name: &str) -> bool {
    name.starts_with("c_")
}

#[test]
fn a_maximum_size_does_not_clamp_a_size_the_item_states() {
    check_group(stated_widths);
}

fn unchanged(name: &str) -> bool {
    name.starts_with("d_")
}

#[test]
fn items_that_were_already_sized_as_in_chromium_keep_their_boxes() {
    check_group(unchanged);
}

/// A case that no group selects would never be run.
#[test]
fn every_case_is_in_a_group() {
    let groups: &[fn(&str) -> bool] = &[
        percentage_heights,
        maximum_heights,
        stated_widths,
        unchanged,
    ];
    for case in CASES {
        assert!(
            groups.iter().any(|group| group(case.0)),
            "{}: no group runs it",
            case.0
        );
    }
}

